@keyframes newIn{from{opacity:0;transform:scale(.98)}to{opacity:1;transform:scale(1)}}
@keyframes sheetIn{from{opacity:0;transform:translateY(100%)}to{opacity:1;transform:none}}
.toast{
  display:flex;align-items:center;gap:12px;background:#12C55B;border:0;color:#fff;
  border-radius:6px;padding:13px 16px;min-width:280px;
  box-shadow:0 4px 16px rgba(0,0,0,.1);animation:toastIn .2s cubic-bezier(.4,0,.2,1);
}
@keyframes toastIn{from{opacity:0;transform:translateY(-10px)}to{opacity:1;transform:none}}
.toast.out{animation:toastOut .2s cubic-bezier(.4,0,.2,1) forwards}
@keyframes toastOut{to{opacity:0;transform:translateY(-10px)}}
.toast .tk{width:30px;height:30px;border-radius:50%;background:rgba(255,255,255,.18);color:#fff;
  display:flex;align-items:center;justify-content:center;font-size:15px;flex-shrink:0}
.toast .tt{flex:1;font-size:13.5px;font-weight:600;color:#fff}
.toast .tv{color:#fff;font-size:13px;font-weight:700}
.toast .tv:hover{text-decoration:underline}
@keyframes tshimmer{to{transform:translateX(100%)}}
@keyframes nfFlash{0%{background:rgba(0,172,172,.22)}100%{background:rgba(0,172,172,.06)}}
@keyframes jiggle{
  0%{transform:rotate(-1.4deg) translate(-.5px,.5px)}
  50%{transform:rotate(1.4deg) translate(.5px,-.5px)}
  100%{transform:rotate(-1.7deg)}
}
@keyframes crspin{to{transform:rotate(360deg)}}
.reels-player.open{display:flex}
.rp-close{position:absolute;top:18px;right:24px;z-index:8;width:48px;height:48px;border-radius:50%;border:0;cursor:pointer;
  background:rgba(255,255,255,.14);color:#fff;font-size:22px;display:flex;align-items:center;justify-content:center;transition:background .15s}
.rp-close:hover{background:rgba(255,255,255,.26)}
.rv-feed{flex:1;display:flex;flex-direction:column;overflow-y:auto;overflow-x:hidden;scroll-snap-type:y mandatory;scroll-behavior:smooth;overscroll-behavior:contain;scrollbar-width:none}
.rv-feed::-webkit-scrollbar{display:none}
.rv-reel{flex:0 0 100%;width:100%;height:100%;scroll-snap-align:start;scroll-snap-stop:always;display:flex;align-items:center;justify-content:center}
.rv-timer{position:absolute;left:0;right:0;bottom:0;z-index:5;height:3px;background:rgba(255,255,255,.28)}
.rv-timer span{display:block;height:100%;width:0;background:#fff}
.rv-reel.playing .rv-timer span{animation:rvTick 30s cubic-bezier(.2,.42,.75,1) forwards}
.rv-timer.isvid span{animation:none !important;transition:width 120ms linear}
@keyframes rvTick{from{width:0}to{width:100%}}
.rv-tap{position:absolute;inset:0;z-index:3;cursor:pointer}
.rv-pauseic{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%) scale(.85);z-index:7;
  width:74px;height:74px;border-radius:50%;background:rgba(28,28,30,.55);color:#fff;font-size:28px;
  display:flex;align-items:center;justify-content:center;opacity:0;pointer-events:none;
  transition:opacity 200ms cubic-bezier(.4,0,.2,1),transform 200ms cubic-bezier(.4,0,.2,1)}
.rv-reel.paused .rv-pauseic{opacity:1;transform:translate(-50%,-50%) scale(1)}
.rv-reel.paused .rv-timer span{animation-play-state:paused !important}
.rv-card{position:relative;height:min(90%,calc(100vh - 40px));aspect-ratio:9/16;border-radius:14px;overflow:hidden;
  background:#111;box-shadow:0 24px 70px rgba(0,0,0,.6)}
.rv-card>img,.rv-card>video{width:100%;height:100%;object-fit:cover;display:block}
.rv-card>img.wide,.rv-card>video.wide{object-fit:contain;background:#000}
.rv-card::after{content:'';position:absolute;inset:0;pointer-events:none;
  background:linear-gradient(180deg,rgba(0,0,0,.32) 0%,transparent 14%,transparent 88%,rgba(0,0,0,.45) 100%)}
.rv-badge{position:absolute;top:24px;left:14px;z-index:3;display:flex;align-items:center;gap:6px;
  font-size:11px;font-weight:700;color:#fff;background:rgba(0,0,0,.58);
  padding:6px 11px;border-radius:999px}
.rv-badge i{font-size:11px;color:#ffd76a}
.rv-rail{position:absolute;right:12px;bottom:20px;z-index:3;display:flex;flex-direction:column;gap:18px;align-items:center}
.rv-act{display:flex;flex-direction:column;align-items:center;gap:5px}
.rv-act button{width:46px;height:46px;border-radius:50%;border:0;cursor:pointer;
  background:rgba(0,0,0,.32);color:#fff;font-size:20px;display:flex;align-items:center;justify-content:center;
  transition:transform .12s,background .15s}
.rv-act button:hover{background:rgba(0,0,0,.5)}
.rv-act button:active{transform:scale(.88)}
.rv-act span{font-size:12px;font-weight:600;color:#fff;text-shadow:0 1px 4px rgba(0,0,0,.5)}
.rv-act.like.on button{color:#ff3040}
.rv-act.save.on button{color:#ffd76a}
.rv-info{position:absolute;left:16px;right:74px;bottom:20px;z-index:3;color:#fff}
.rv-author{display:flex;align-items:center;gap:10px;margin-bottom:9px}
.rv-author .avatar{width:34px;height:34px;font-size:12px;border:2px solid #fff}
.rv-name{font-size:14px;font-weight:700;text-shadow:0 1px 4px rgba(0,0,0,.5)}
.rv-follow{margin-left:2px;font-size:12px;font-weight:700;color:#fff;background:transparent;
  border:1px solid rgba(255,255,255,.7);border-radius:8px;padding:4px 13px;cursor:pointer;transition:background .15s}
.rv-follow:hover{background:rgba(255,255,255,.15)}
.rv-follow.following{border-color:rgba(255,255,255,.3);opacity:.85}
.rv-caption{cursor:pointer;font-size:13px;line-height:1.45;text-shadow:0 1px 6px rgba(0,0,0,.6);
  display:-webkit-box;-webkit-line-clamp:2;line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.rv-music{display:flex;align-items:center;gap:8px;margin-top:10px;font-size:12px;opacity:.92;text-shadow:0 1px 4px rgba(0,0,0,.6)}
.rv-nav{position:absolute;left:auto;right:24px;top:50%;transform:translateY(-50%);z-index:6;display:flex;flex-direction:column;gap:14px;padding:0;pointer-events:none}
.rv-audio{position:absolute;top:14px;left:14px;z-index:8;display:flex;align-items:center;gap:0;
  border-radius:32px;transition:background 120ms cubic-bezier(.4,0,.2,1),padding 120ms cubic-bezier(.4,0,.2,1)}
.rv-audio:hover,.rv-audio:focus-within{background:rgba(28,28,30,.55);padding-right:12px;gap:8px}
.rv-mute{width:36px;height:36px;border:0;border-radius:50%;flex-shrink:0;
  background:none;color:#fff;font-size:17px;cursor:pointer;display:flex;align-items:center;justify-content:center;
  transition:background 120ms cubic-bezier(.4,0,.2,1)}
.rv-mute:hover{background:rgba(255,255,255,.08)}
.rv-vol{width:0;opacity:0;pointer-events:none;height:4px;-webkit-appearance:none;appearance:none;
  background:rgba(255,255,255,.32);border-radius:32px;outline:none;cursor:pointer;
  transition:width 120ms cubic-bezier(.4,0,.2,1),opacity 120ms cubic-bezier(.4,0,.2,1)}
.rv-audio:hover .rv-vol,.rv-audio:focus-within .rv-vol{width:82px;opacity:1;pointer-events:auto}
.rv-vol::-webkit-slider-thumb{-webkit-appearance:none;width:12px;height:12px;border-radius:50%;background:#fff;cursor:pointer}
.rv-vol::-moz-range-thumb{width:12px;height:12px;border:0;border-radius:50%;background:#fff;cursor:pointer}
.rv-mute:focus-visible{outline:none;box-shadow:0 0 0 2px rgba(0,136,255,.16)}
.rv-nav button{pointer-events:auto;width:50px;height:50px;border-radius:50%;border:0;cursor:pointer;
  background:rgba(255,255,255,.12);color:#fff;font-size:19px;display:flex;align-items:center;justify-content:center;transition:background .15s}
.rv-nav button:hover{background:rgba(255,255,255,.24)}
@media (max-width:640px){
.rv-nav{display:none}
.rv-card{height:100%;width:100%;border-radius:0;aspect-ratio:auto}

}
